#define main solve_main
#include "solve.cpp"
#undef main
struct Path{int z;vector<string> m;};
string flip(string s){auto k=s.find('v');return s.substr(k+1)+"v"+s.substr(0,k);}
map<string,pair<int,bool>> lookup;map<pair<string,int>,set<string>> adj;map<string,vector<U>> dummy;
string key(Path p){string s=to_string(p.z);for(auto&m:p.m)s+="/"+m;return s;}
Path canon(Path p){if(lookup.at(p.m[0]).second){p.z=-p.z;for(auto&m:p.m)m=flip(m);}return p;}
struct Mask{vector<uint64_t>b;long n=0;Mask(int s):b((s+63)/64){}bool get(U i)const{return (b[i>>6]>>(i&63))&1;}bool add(U i){if(get(i))return false;b[i>>6]|=1ull<<(i&63);n++;return true;}};
map<string,shared_ptr<Mask>> cache;
Path tail(Path p){p.m.erase(p.m.begin());return canon(p);}
bool nextmatch(const Tab&t,const Pos&p,Move m,Pos v,const Path&path,const Mask*mask,Pos*res=nullptr,int*rid=nullptr){if(m.cap<0&&!m.pr)return false;auto [id,q]=child(t,p,m,v);bool sw=q.turn!=1-p.turn;if(mat(ts[id],sw)!=path.m[1])return false;int z=ts[id].v[enc(ts[id],q)];if(pc(z)*(sw?-1:1)!=path.z)return false;if(mask&&!mask->get(enc(ts[id],q)))return false;if(res)*res=q;if(rid)*rid=id;return true;}
shared_ptr<Mask> getmask(Path path){path=canon(path);string k=key(path);if(cache.count(k))return cache[k];int id=lookup.at(path.m[0]).first;Tab&t=ts[id];auto mask=make_shared<Mask>(t.sz);shared_ptr<Mask> sub;if(path.m.size()>2)sub=getmask(tail(path));vector<U>q;for(U a=0;a<(U)t.sz;a++){int z=t.v[a];if(z==INV||pc(z)!=path.z)continue;if(path.m.size()==1){mask->add(a);continue;}if(z==DEAD)continue;Pos p=dec(t,a);bool yes=false;moves(t,p,[&](Move m,Pos v){if(!yes&&nextmatch(t,p,m,v,path,sub.get()))yes=true;},true);if(yes){mask->add(a);q.push_back(a);}}
for(size_t j=0;j<q.size();j++){Pos p=dec(t,q[j]);preds(t,p,[&](U a){if(t.v[a]==path.z&&mask->add(a))q.push_back(a);});}cache[k]=mask;cerr<<"mask "<<k<<" "<<mask->n<<endl;return mask;}
// find concrete quiet path to an exit. Queue stores unreflected position so each certificate is continuous.
struct Step{int id;Pos p;Move m;bool sw;};
bool witness(Path path,int id,Pos start,bool overall,vector<Step>&out){path=canon(path);if(path.m.size()==1)return true;Tab&t=ts[id];shared_ptr<Mask>sub;if(path.m.size()>2)sub=getmask(tail(path));struct Node{Pos p;int parent;Move m;};vector<Node>q{{start,-1,{}}};unordered_set<U>seen{enc(t,start)};for(size_t j=0;j<q.size();j++){Pos p=q[j].p;bool done=false;Move em{};Pos ep{};int eid=-1; moves(t,p,[&](Move m,Pos v){if(done)return;if(nextmatch(t,p,m,v,path,sub.get(),&ep,&eid)){done=true;em=m;}},true);if(done){vector<Step>pre;int i=j;while(q[i].parent>=0){int par=q[i].parent;pre.push_back({id,q[par].p,q[i].m,overall});i=par;}reverse(pre.begin(),pre.end());out.insert(out.end(),pre.begin(),pre.end());out.push_back({id,p,em,overall});bool sw=ep.turn!=1-p.turn;return witness(tail(path),eid,ep,overall^sw,out);}moves(t,p,[&](Move m,Pos v){if(m.cap>=0||m.pr)return;v.turn=1-p.turn;v.ep=m.ep;U a=enc(t,v);if(t.v[a]==path.z&&seen.insert(a).second)q.push_back({v,(int)j,m});});}return false;}
void pathsfrom(Path p,vector<Path>&all){if(p.m.size()>1)all.push_back(p);for(auto&m:adj[{p.m.back(),p.z}]){Path r=p;r.m.push_back(m);pathsfrom(r,all);}}
int main(){init();setup();load();for(int i=0;i<(int)ts.size();i++){lookup[mat(ts[i])]={i,false};if(mat(ts[i],true)!=mat(ts[i]))lookup[mat(ts[i],true)]={i,true};}ifstream f("results.tsv");string line;set<pair<string,int>>verts;while(getline(f,line)){stringstream ss(line);string s,a,b,z;getline(ss,s,'\t');getline(ss,a,'\t');getline(ss,b,'\t');if(s=="V"){int v=stoi(b);verts.insert({a,v});verts.insert({flip(a),-v});}else{getline(ss,z,'\t');int v=stoi(z);adj[{a,v}].insert(b);adj[{flip(a),-v}].insert(flip(b));}}
vector<Path>all;for(auto [m,z]:verts)pathsfrom({z,{m}},all);sort(all.begin(),all.end(),[](auto&a,auto&b){return a.m.size()<b.m.size();});ofstream of("paths.tsv");set<string>done;int good=0,bad=0;for(auto p:all){p=canon(p);string k=key(p);if(!done.insert(k).second)continue;auto &t=ts[lookup.at(p.m[0]).first];shared_ptr<Mask>sub;if(p.m.size()>2)sub=getmask(tail(p));bool found=false;vector<Step>out;for(U a=0;a<(U)t.sz&&!found;a++){int z=t.v[a];if(z!=p.z)continue;Pos x=dec(t,a);moves(t,x,[&](Move m,Pos v){if(found)return;Pos q;int id;if(nextmatch(t,x,m,v,p,sub.get(),&q,&id)){found=true;out.push_back({int(&t-&ts[0]),x,m,false});assert(witness(tail(p),id,q,q.turn!=1-x.turn,out));}},true);}
of<<k<<'\t'<<(found?"YES":"NO");if(found){good++;for(auto&s:out)of<<'\t'<<s.sw<<':'<<fen(ts[s.id],s.p)<<':'<<uci(s.p,s.m);}else{bad++;cerr<<"FALSE "<<k<<endl;}of<<'\n';of.flush();}cerr<<"PATHS canonical "<<good<<" yes "<<bad<<" no; full "<<all.size()<<endl;}
